import{_ as e,c as a,o as d,b2 as i}from"./chunks/framework.CUhoHPxN.js";const u=JSON.parse('{"title":"环境搭建","description":"","frontmatter":{},"headers":[],"relativePath":"docs/guide/installation.md","filePath":"docs/guide/installation.md"}'),o={name:"docs/guide/installation.md"};function l(s,t,r,n,c,h){return d(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="环境搭建" tabindex="-1">环境搭建 <a class="header-anchor vp-link" href="#环境搭建" aria-label="Permalink to &quot;环境搭建&quot;">​</a></h1><h2 id="必需软件" tabindex="-1">必需软件 <a class="header-anchor vp-link" href="#必需软件" aria-label="Permalink to &quot;必需软件&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>软件</th><th>版本建议</th><th>用途</th></tr></thead><tbody><tr><td>JDK</td><td>17+</td><td>编译与运行 quickboot</td></tr><tr><td>Maven</td><td>3.6+</td><td>后端构建</td></tr><tr><td>Node.js</td><td>18 或 20 LTS</td><td>quick-ui、docs</td></tr><tr><td>pnpm</td><td>9.x（与 <code>quick-ui/package.json</code> 一致）</td><td>前端/文档包管理</td></tr></tbody></table></div><h2 id="可选-按环境" tabindex="-1">可选（按环境） <a class="header-anchor vp-link" href="#可选-按环境" aria-label="Permalink to &quot;可选（按环境）&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>软件</th><th>用途</th></tr></thead><tbody><tr><td>MySQL 8+</td><td>生产/联调数据库（<code>application-prod.yml</code>）</td></tr><tr><td>Redis</td><td>生产 Token、nonce 防重放、验证码存储等</td></tr><tr><td>Git</td><td>克隆仓库</td></tr></tbody></table></div><h2 id="后端配置要点" tabindex="-1">后端配置要点 <a class="header-anchor vp-link" href="#后端配置要点" aria-label="Permalink to &quot;后端配置要点&quot;">​</a></h2><h3 id="开发-默认-dev-profile" tabindex="-1">开发（默认 <code>dev</code> Profile） <a class="header-anchor vp-link" href="#开发-默认-dev-profile" aria-label="Permalink to &quot;开发（默认 `dev` Profile）&quot;">​</a></h3><ul><li>数据源：H2 文件模式，路径 <code>./data/qcc</code></li><li>H2 Console：开发配置下可开启（注意勿暴露到公网）</li><li>Token 存储：<code>qc.oauth2.token-store=local</code>（单实例）</li><li>启动参数示例：</li></ul><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span>-Djasypt.encryptor.password=&lt;你的加密密钥&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="生产-prod-profile" tabindex="-1">生产（<code>prod</code> Profile） <a class="header-anchor vp-link" href="#生产-prod-profile" aria-label="Permalink to &quot;生产（`prod` Profile）&quot;">​</a></h3><ul><li>数据源：MySQL，敏感项建议 Jasypt <code>ENC(...)</code> 包裹</li><li>Token / 缓存：建议 Redis（<code>qc.oauth2.token-store=redis</code>）</li><li>关闭 Druid 监控页、收紧 <code>qc.security.web.anonymous-paths</code></li></ul><p>配置文件位置：</p><ul><li><code>quickboot/quickboot-web/src/main/resources/application.yml</code></li><li><code>application-dev.yml</code> / <code>application-prod.yml</code></li></ul><h2 id="前端配置要点" tabindex="-1">前端配置要点 <a class="header-anchor vp-link" href="#前端配置要点" aria-label="Permalink to &quot;前端配置要点&quot;">​</a></h2><p>文件：<code>quick-ui/.env.development</code>（勿将生产密钥提交仓库）</p><div class="vp-table"><table><thead><tr><th>变量</th><th>说明</th></tr></thead><tbody><tr><td><code>VITE_APP_BASE_API</code></td><td>后端 API 根路径（含 <code>/dev-api</code> 等前缀时与代理一致）</td></tr><tr><td><code>VITE_APP_CLIENT_ID</code></td><td>OAuth Client HMAC，默认 <code>quick-ui</code></td></tr><tr><td><code>VITE_APP_CLIENT_SIGN_KEY</code></td><td>与库中 <code>client_secret</code> 明文一致</td></tr></tbody></table></div><h2 id="文档站" tabindex="-1">文档站 <a class="header-anchor vp-link" href="#文档站" aria-label="Permalink to &quot;文档站&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#998418;--shiki-dark:#B8A965;">cd</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> docs</span><span style="--shiki-light:#999999;--shiki-dark:#666666;"> &amp;&amp;</span><span style="--shiki-light:#59873A;--shiki-dark:#80A665;"> pnpm</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> i</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>无额外数据库依赖。</p><h2 id="ide-建议" tabindex="-1">IDE 建议 <a class="header-anchor vp-link" href="#ide-建议" aria-label="Permalink to &quot;IDE 建议&quot;">​</a></h2><ul><li>后端：IntelliJ IDEA，启用 Lombok、Annotation Processing</li><li>前端：VS Code / Cursor，推荐 Volar、ESLint</li><li>统一编码：<strong>UTF-8 无 BOM</strong>（见仓库 <code>AGENTS.md</code>）</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor vp-link" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p><a href="./quick-start.html" class="vp-link">快速上手</a></p>',23)])])}const k=e(o,[["render",l]]);export{u as __pageData,k as default};
